import type { BankQuestion } from "@/lib/bank";

/** International Organisations and Groupings (General Knowledge): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "gk-international-orgs-1", "question": "The headquarters of the United Nations is in:", "options": ["Geneva", "New York", "Washington, D.C.", "Paris"], "answer": 1, "explanation": "The UN headquarters is in New York; its main European office is at Geneva.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"gk-international-orgs-2","question":"The headquarters of the World Trade Organization (WTO) is in:","options":["New York","Vienna","Geneva","Brussels"],"answer":2,"explanation":"The WTO, successor to GATT since 1995, is headquartered in Geneva, Switzerland. Vienna is the trap: it hosts the IAEA, OPEC and UNIDO, not the WTO.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-3", "question": "United Nations Day is observed every year on:", "options": ["26 June", "10 December", "24 October", "1 January"], "answer": 2, "explanation": "The UN Charter came into force on 24 October 1945. It was signed on 26 June 1945; 10 December is Human Rights Day.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-4", "question": "The secretariat of SAARC is located in:", "options": ["Kathmandu", "New Delhi", "Colombo", "Dhaka"], "answer": 0, "explanation": "The SAARC Secretariat has been in Kathmandu since 1987. SAARC itself was founded at Dhaka in 1985.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-5", "question": "The IMF and the World Bank were created at a conference held in 1944 at:", "options": ["Bretton Woods", "San Francisco", "Yalta", "Geneva"], "answer": 0, "explanation": "The Bretton Woods Conference (New Hampshire, USA, July 1944) set up the IMF and the IBRD, so they are called the Bretton Woods twins. The UN Charter was signed at San Francisco.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-6", "question": "Which of the following is NOT a permanent member of the UN Security Council?", "options": ["China", "United Kingdom", "France", "Germany"], "answer": 3, "explanation": "The five permanent members are the USA, the UK, France, Russia and China. Germany, like India, seeks a permanent seat (the G4 group).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-7", "question": "The secretariat of ASEAN is in:", "options": ["Jakarta", "Bangkok", "Kuala Lumpur", "Singapore"], "answer": 0, "explanation": "The ASEAN Secretariat is in Jakarta. ASEAN was founded by the Bangkok Declaration of 1967, which is why Bangkok is the trap.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-8", "question": "The headquarters of the World Health Organization is in:", "options": ["Rome", "Geneva", "Vienna", "New York"], "answer": 1, "explanation": "WHO, founded in 1948, is based at Geneva. Rome hosts the FAO and Vienna the IAEA.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"gk-international-orgs-9","question":"The headquarters of UNESCO is in:","options":["Geneva","London","Brussels","Paris"],"answer":3,"explanation":"UNESCO is headquartered in Paris, France. Geneva is the tempting wrong pick because it hosts many UN bodies such as the WHO and ILO, but not UNESCO.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-10", "question": "Which country joined BRIC in 2010, making it BRICS?", "options": ["South Africa", "Saudi Arabia", "Argentina", "Indonesia"], "answer": 0, "explanation": "South Africa was invited in December 2010 and attended its first summit in 2011.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-11", "question": "The secretariat of the Shanghai Cooperation Organisation (SCO) is in:", "options": ["Tashkent", "Shanghai", "Beijing", "Moscow"], "answer": 2, "explanation": "The SCO Secretariat is in Beijing; its Regional Anti-Terrorist Structure (RATS) is in Tashkent.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-12", "question": "The International Court of Justice sits at:", "options": ["New York", "Vienna", "The Hague", "Geneva"], "answer": 2, "explanation": "The ICJ, the UN’s principal judicial organ, sits at the Peace Palace in The Hague, Netherlands; it is the only principal organ not based in New York.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-13", "question": "The World Trade Organization was established under which agreement, concluding the Uruguay Round?", "options": ["Doha Declaration", "Havana Charter", "Bali Package", "Marrakesh Agreement"], "answer": 3, "explanation": "The Marrakesh Agreement (April 1994) set up the WTO from 1 January 1995. The Havana Charter (1948) for an International Trade Organization never came into force; Doha (2001) launched a new round and the Bali Package came in 2013.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "gk-international-orgs-14", "question": "The International Court of Justice has how many judges, and for what term?", "options": ["15 judges for 5-year terms", "9 judges for 6-year terms", "11 judges for 9-year terms", "15 judges for 9-year terms"], "answer": 3, "explanation": "The ICJ has 15 judges elected by the General Assembly and the Security Council for nine-year terms; a third of the bench is elected every three years.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-15", "question": "The UN Security Council has how many non-permanent members, and for what term?", "options": ["10 members for two-year terms", "6 members for two-year terms", "15 members for two-year terms", "10 members for three-year terms"], "answer": 0, "explanation": "There are 10 non-permanent members elected by the General Assembly for two years (5 each year), making 15 members in all with the 5 permanent members.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-16", "question": "At the G20 Leaders’ Summit in New Delhi in September 2023, which body was admitted as a permanent member of the G20?", "options": ["Arab League", "European Union", "African Union", "ASEAN"], "answer": 2, "explanation": "The African Union joined the G20 at the New Delhi summit under India’s presidency. The European Union was already a member.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-17", "question": "India became a full member of the Shanghai Cooperation Organisation in:", "options": ["2001", "2005", "2017", "2015"], "answer": 2, "explanation": "India and Pakistan became full members at the Astana summit in June 2017; India had been an observer since 2005. The SCO was founded in 2001.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "gk-international-orgs-18", "question": "Which of these currencies is NOT in the basket that values the IMF’s Special Drawing Rights (SDR)?", "options": ["Swiss franc", "Chinese renminbi", "Pound sterling", "Japanese yen"], "answer": 0, "explanation": "The SDR basket has five currencies: US dollar, euro, Chinese renminbi (added in 2016), Japanese yen and pound sterling.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-19", "question": "The New Development Bank set up by the BRICS countries has its headquarters in:", "options": ["Shanghai", "Beijing", "New Delhi", "Moscow"], "answer": 0, "explanation": "The NDB is headquartered in Shanghai; its first president was India’s K.V. Kamath. The Asian Infrastructure Investment Bank is in Beijing.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-20", "question": "The Asian Infrastructure Investment Bank (AIIB) has its headquarters in:", "options": ["Beijing", "Shanghai", "Manila", "Singapore"], "answer": 0, "explanation": "The AIIB, which began operations in 2016, is based in Beijing; India is its second-largest shareholder. Manila hosts the Asian Development Bank.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-21", "question": "Which of the following was NOT a founding member of ASEAN in 1967?", "options": ["Indonesia", "Singapore", "Vietnam", "Philippines"], "answer": 2, "explanation": "The five founders were Indonesia, Malaysia, the Philippines, Singapore and Thailand. Vietnam joined in 1995.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-22", "question": "Which country was the last to join SAARC, in 2007?", "options": ["Bhutan", "Afghanistan", "Maldives", "Myanmar"], "answer": 1, "explanation": "SAARC was founded in 1985 by seven countries; Afghanistan became the eighth member in 2007. Myanmar is not a member.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-23", "question": "The Secretary-General of the United Nations is appointed by the:", "options": ["General Assembly alone", "Security Council alone", "International Court of Justice", "General Assembly on the recommendation of the Security Council"], "answer": 3, "explanation": "Under Article 97 of the UN Charter, the General Assembly appoints the Secretary-General on the Security Council’s recommendation, so a permanent member can veto a candidate.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-24", "question": "Which of these is NOT an official language of the United Nations?", "options": ["Arabic", "Russian", "Portuguese", "Spanish"], "answer": 2, "explanation": "The six official UN languages are Arabic, Chinese, English, French, Russian and Spanish.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-25", "question": "Match the organisation with its headquarters: 1. Food and Agriculture Organization  2. International Labour Organization  3. International Atomic Energy Agency  4. UN Environment Programme; a. Rome  b. Vienna  c. Nairobi  d. Geneva", "options": ["1-a, 2-d, 3-c, 4-b", "1-a, 2-b, 3-d, 4-c", "1-a, 2-d, 3-b, 4-c", "1-d, 2-a, 3-b, 4-c"], "answer": 2, "explanation": "FAO: Rome; ILO: Geneva; IAEA: Vienna; UNEP: Nairobi (the first UN agency headquartered in the Global South).", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "gk-international-orgs-26", "question": "How many of these statements about the principal organs of the UN are correct? I. The Trusteeship Council suspended its operations in 1994. II. The Economic and Social Council has 54 members. III. The International Court of Justice is located in New York. IV. UNICEF is one of the six principal organs.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. The ICJ is at The Hague (III wrong). The six principal organs are the General Assembly, Security Council, ECOSOC, Trusteeship Council, ICJ and Secretariat; UNICEF is a fund created by the General Assembly (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-27", "question": "Assertion (A): The International Development Association (IDA) gives concessional loans and grants to the poorest countries. Reason (R): The IBRD lends to middle-income and creditworthy low-income countries on near-market terms.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true, but R does not explain A. They describe two different arms of the World Bank; R explains the IBRD’s role, not why the IDA lends on soft terms.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id":"gk-international-orgs-28","question":"Arrange the founding of these organisations in chronological order: 1. SAARC  2. NATO  3. WTO  4. ASEAN","options":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"answer":0,"explanation":"NATO was founded in 1949, ASEAN in 1967, SAARC in 1985 and the WTO in 1995, giving 2, 4, 1, 3. The trap 4, 2, 1, 3 assumes ASEAN is older than NATO, and 2, 4, 3, 1 wrongly places the WTO before SAARC.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · UPSC Prelims"},
  {"id":"gk-international-orgs-29","question":"How many of these statements about BRICS are correct? I. Egypt and Ethiopia became members in January 2024. II. The first BRIC summit was held in Brazil in 2009. III. The New Development Bank is headquartered in New Delhi. IV. Argentina joined BRICS in January 2024.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct (Egypt, Ethiopia, Iran and the UAE joined in 2024). The first BRIC summit was held at Yekaterinburg, Russia, in 2009; the New Development Bank is headquartered in Shanghai; and Argentina declined its 2023 invitation.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-30", "question": "Which of the following is NOT a specialised agency of the United Nations?", "options": ["UNICEF", "UNESCO", "International Labour Organization", "World Health Organization"], "answer": 0, "explanation": "UNICEF is a fund (subsidiary body) of the General Assembly, not a specialised agency. UNESCO, WHO and ILO are specialised agencies with their own membership and budgets.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-31", "question": "Match the grouping with the year it was founded: 1. G20  2. Shanghai Cooperation Organisation  3. BIMSTEC  4. IBSA Dialogue Forum; a. 2001  b. 1999  c. 2003  d. 1997", "options": ["1-b, 2-d, 3-a, 4-c", "1-b, 2-a, 3-d, 4-c", "1-a, 2-b, 3-d, 4-c", "1-b, 2-a, 3-c, 4-d"], "answer": 1, "explanation": "G20: 1999 (after the Asian financial crisis); SCO: 2001; BIMSTEC: 1997 (Bangkok Declaration); IBSA: 2003 (Brasilia Declaration).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-32", "question": "How many of these statements are correct? I. The IMF is headquartered in Washington, D.C. II. The World Bank is headquartered in Washington, D.C. III. By convention the World Bank President is an American and the IMF Managing Director a European. IV. India is a founding member of the IMF.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Both Bretton Woods institutions are in Washington, D.C.; the US–Europe leadership convention has held since 1946; India attended Bretton Woods and was a founding member.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-33", "question": "Assertion (A): Any one permanent member of the UN Security Council can block a substantive resolution. Reason (R): Substantive decisions need nine affirmative votes including the concurring votes of all permanent members.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: because Article 27(3) requires the concurrence of all five permanent members, a single negative vote (the veto) defeats the resolution. An abstention, by practice, does not count as a veto.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-34", "question": "Match the year with the country that held the G20 presidency: 1. 2022  2. 2023  3. 2024  4. 2025; a. Indonesia  b. Brazil  c. India  d. South Africa", "options": ["1-a, 2-c, 3-b, 4-d", "1-c, 2-a, 3-b, 4-d", "1-a, 2-c, 3-d, 4-b", "1-a, 2-b, 3-c, 4-d"], "answer": 0, "explanation": "Indonesia (Bali, 2022), India (New Delhi, 2023), Brazil (Rio de Janeiro, 2024) and South Africa (Johannesburg, 2025), the first time four developing countries held it in a row.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-35", "question": "How many of these statements are correct? I. The BIMSTEC Secretariat is in Dhaka. II. Thailand is a member of both SAARC and BIMSTEC. III. Bhutan and Nepal are members of both SAARC and BIMSTEC. IV. The Maldives is a member of BIMSTEC.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. Thailand is in BIMSTEC but not SAARC (II wrong), and the Maldives is in SAARC but not BIMSTEC (IV wrong). BIMSTEC’s members are Bangladesh, Bhutan, India, Myanmar, Nepal, Sri Lanka and Thailand.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-36", "question": "Which of the following is NOT a member of the G7?", "options": ["Russia", "Japan", "Canada", "Italy"], "answer": 0, "explanation": "The G7 is the USA, UK, France, Germany, Japan, Italy and Canada, with the EU attending. Russia joined to form the G8 in 1997 but was suspended in 2014 after annexing Crimea.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-37", "question": "Match the organisation with its role: 1. Financial Action Task Force  2. Bank for International Settlements  3. OECD  4. World Intellectual Property Organization; a. Bank for central banks  b. Standards against money laundering and terror financing  c. Policy forum mainly of developed market economies  d. Protection of patents, copyrights and trademarks", "options": ["1-b, 2-c, 3-a, 4-d", "1-a, 2-b, 3-c, 4-d", "1-b, 2-a, 3-d, 4-c", "1-b, 2-a, 3-c, 4-d"], "answer": 3, "explanation": "FATF (Paris) sets anti-money-laundering standards and keeps the grey and black lists; BIS (Basel) is the central bankers’ bank; OECD (Paris) is a policy forum of mostly rich economies; WIPO (Geneva) handles intellectual property.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-international-orgs-38", "question": "How many of these statements about the WTO are correct? I. Its highest decision-making body is the Ministerial Conference. II. The Ministerial Conference meets at least once every two years. III. India is a founding member of the WTO. IV. The 12th Ministerial Conference (2022) was held in Nairobi.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. MC12 was held in Geneva in June 2022; Nairobi hosted MC10 in 2015 (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-39", "question": "Assertion (A): Switzerland became a member of the United Nations only in 2002. Reason (R): Switzerland has a long tradition of neutrality, and its voters had earlier rejected UN membership.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: fears that membership would compromise neutrality led Swiss voters to reject joining in a 1986 referendum; a 2002 referendum approved it.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-40", "question": "Match the organisation with the year it was founded: 1. United Nations  2. League of Nations  3. African Union  4. OPEC; a. 1920  b. 2002  c. 1960  d. 1945", "options": ["1-d, 2-b, 3-a, 4-c", "1-d, 2-a, 3-b, 4-c", "1-d, 2-a, 3-c, 4-b", "1-a, 2-d, 3-b, 4-c"], "answer": 1, "explanation": "UN: 1945; League of Nations: 1920; African Union: 2002 (succeeding the OAU of 1963); OPEC: 1960 (Baghdad).", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · UPSC Prelims"},
  {"id": "gk-international-orgs-41", "question": "The headquarters of UNICEF is in:", "options": ["Geneva", "Paris", "New York", "Vienna"], "answer": 2, "explanation": "UNICEF (founded 1946) is headquartered in New York. Many other UN bodies are in Geneva, which makes it the tempting wrong answer.", "difficulty": "easy", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-42", "question": "The headquarters of NATO is in:", "options": ["Brussels", "Washington, D.C.", "London", "The Hague"], "answer": 0, "explanation": "NATO's headquarters moved from Paris to Brussels in 1967, after France left the integrated military command.", "difficulty": "easy", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-43", "question": "The International Committee of the Red Cross (ICRC) is headquartered in:", "options": ["New York", "Vienna", "Paris", "Geneva"], "answer": 3, "explanation": "The ICRC was founded in Geneva in 1863 by Henry Dunant and others and is still based there.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-international-orgs-44", "question": "The Commonwealth Secretariat is located in:", "options": ["Ottawa", "London", "Canberra", "New Delhi"], "answer": 1, "explanation": "The Commonwealth Secretariat, set up in 1965, is at Marlborough House, London.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-international-orgs-45", "question": "Amnesty International, the human rights organisation, has its headquarters in:", "options": ["London", "Geneva", "Stockholm", "New York"], "answer": 0, "explanation": "Amnesty International was founded in London in 1961 by Peter Benenson; its International Secretariat is in London.", "difficulty": "easy", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-46", "question": "The Organization of the Petroleum Exporting Countries (OPEC) has its headquarters in:", "options": ["Riyadh", "Vienna", "Geneva", "Kuwait City"], "answer": 1, "explanation": "OPEC was founded at Baghdad in 1960 and moved its secretariat to Vienna in 1965. Austria is not a member.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-47", "question": "The euro was introduced as an accounting (non-cash) currency in:", "options": ["1993", "1999", "2002", "2004"], "answer": 1, "explanation": "The euro began as book money on 1 January 1999; euro notes and coins came into circulation on 1 January 2002.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-48", "question": "The headquarters of Interpol is in:", "options": ["Lyon", "Paris", "Brussels", "Vienna"], "answer": 0, "explanation": "Interpol (founded 1923 in Vienna) has had its General Secretariat in Lyon, France, since 1989.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-49", "question": "The first session of the UN General Assembly was held in January 1946 in:", "options": ["New York", "San Francisco", "London", "Geneva"], "answer": 2, "explanation": "The first session met at Methodist Central Hall, London. The UN Charter had been signed at San Francisco in June 1945.", "difficulty": "moderate", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-50", "question": "The World Wide Fund for Nature (WWF) is headquartered at:", "options": ["Gland, Switzerland", "Nairobi, Kenya", "Washington, D.C.", "Bonn, Germany"], "answer": 0, "explanation": "WWF International is based at Gland, Switzerland; the IUCN is also headquartered there.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-51", "question": "The headquarters of the African Union is in:", "options": ["Nairobi", "Johannesburg", "Addis Ababa", "Cairo"], "answer": 2, "explanation": "The African Union (2002), successor to the OAU (1963), has its headquarters in Addis Ababa, Ethiopia.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-52", "question": "The Quadrilateral Security Dialogue (Quad) brings together India, the United States, Japan and:", "options": ["South Korea", "Australia", "France", "the United Kingdom"], "answer": 1, "explanation": "The Quad comprises India, the USA, Japan and Australia; its leaders first met in 2021.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-53", "question": "UN-Habitat, the UN programme for human settlements, is headquartered in:", "options": ["Nairobi", "Rome", "Bangkok", "Geneva"], "answer": 0, "explanation": "UN-Habitat, like UNEP, has its headquarters in Nairobi, Kenya.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-54", "question": "The International Solar Alliance was launched in 2015 at the COP21 climate summit in Paris by India and:", "options": ["The United States", "Germany", "France", "Japan"], "answer": 2, "explanation": "Prime Minister Modi and President Hollande launched the ISA; its headquarters is at Gurugram, India, making it the first treaty-based international body based in India.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-55", "question": "Which country became the 193rd member of the United Nations in 2011?", "options": ["Montenegro", "Timor-Leste", "South Sudan", "Kosovo"], "answer": 2, "explanation": "South Sudan became independent and joined the UN in July 2011. Kosovo is not a UN member; Montenegro joined in 2006.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-56", "question": "The UN Human Rights Council, set up in 2006, replaced the:", "options": ["UN Trusteeship Council", "UN Commission on Human Rights", "Office of the High Commissioner for Human Rights", "International Labour Organization"], "answer": 1, "explanation": "The 47-member Human Rights Council, based in Geneva, replaced the discredited Commission on Human Rights (1946–2006). The OHCHR still exists as its secretariat.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-57", "question": "The headquarters of the Universal Postal Union is in:", "options": ["Geneva", "Bern", "Vienna", "Paris"], "answer": 1, "explanation": "The UPU, founded in 1874, is based in Bern, Switzerland. World Post Day (9 October) marks its founding.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-58", "question": "Which is the oldest specialised agency in the UN system, founded in 1865?", "options": ["Universal Postal Union", "International Labour Organization", "International Telecommunication Union", "World Meteorological Organization"], "answer": 2, "explanation": "The ITU began as the International Telegraph Union in 1865; the UPU came in 1874 and the ILO in 1919.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-59", "question": "The International Fund for Agricultural Development (IFAD) is headquartered in:", "options": ["Rome", "Nairobi", "Manila", "Geneva"], "answer": 0, "explanation": "IFAD, like the FAO and the World Food Programme, is based in Rome.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-60", "question": "The Asian Development Bank has its headquarters in:", "options": ["Beijing", "Tokyo", "Manila", "Singapore"], "answer": 2, "explanation": "The ADB (1966) is headquartered in Mandaluyong, Metro Manila. Beijing is the seat of the AIIB.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-61", "question": "The Wassenaar Arrangement, which India joined in December 2017, deals with:", "options": ["Export controls on conventional arms and dual-use goods", "Nuclear fuel supply", "Climate finance", "Trade in endangered species"], "answer": 0, "explanation": "The Wassenaar Arrangement (1996) is a voluntary export-control regime for conventional arms and dual-use technologies. India is also in the MTCR and the Australia Group.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-62", "question": "India became a member of the Missile Technology Control Regime (MTCR) in:", "options": ["2008", "2016", "2018", "2020"], "answer": 1, "explanation": "India joined the MTCR in June 2016, the Wassenaar Arrangement in 2017 and the Australia Group in 2018. It is still not in the Nuclear Suppliers Group.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-63", "question": "The Nuclear Suppliers Group was formed in 1974 in response to:", "options": ["The Chernobyl accident", "India's first nuclear test", "China's first nuclear test", "The signing of the NPT"], "answer": 1, "explanation": "India's 'peaceful nuclear explosion' at Pokhran in May 1974 led supplier countries to form the NSG to control nuclear exports. Chernobyl was in 1986.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-64", "question": "The secretariat of the Indian Ocean Rim Association (IORA) is located at:", "options": ["Ebene, Mauritius", "Colombo, Sri Lanka", "Perth, Australia", "Durban, South Africa"], "answer": 0, "explanation": "IORA, founded in 1997, has its secretariat at Ebene, Mauritius.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-65", "question": "Which of the following is NOT a member of the Mekong–Ganga Cooperation?", "options": ["Laos", "Cambodia", "Malaysia", "Vietnam"], "answer": 2, "explanation": "The Mekong–Ganga Cooperation (2000) has six members: India, Cambodia, Laos, Myanmar, Thailand and Vietnam. Malaysia is not on the Mekong.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-66", "question": "Which country became the 32nd member of NATO in March 2024?", "options": ["Finland", "Sweden", "Ukraine", "Montenegro"], "answer": 1, "explanation": "Sweden joined on 7 March 2024; Finland had joined in April 2023 as the 31st member, both after Russia's invasion of Ukraine.", "difficulty": "hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-67", "question": "As of its 2021–22 term, how many times has India served as a non-permanent member of the UN Security Council?", "options": ["Six", "Seven", "Eight", "Nine"], "answer": 2, "explanation": "India has been elected eight times: 1950–51, 1967–68, 1972–73, 1977–78, 1984–85, 1991–92, 2011–12 and 2021–22.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-68", "question": "Match the UN specialised agency with its headquarters: A. UNIDO B. ICAO C. IMO D. WMO — 1. Geneva 2. London 3. Montreal 4. Vienna", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "UNIDO – Vienna; ICAO (civil aviation) – Montreal; IMO (maritime) – London; WMO (meteorology) – Geneva.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-69", "question": "Arrange in chronological order: 1. The European Union comes into being under the Maastricht Treaty 2. The Treaty of Rome sets up the European Economic Community 3. The United Kingdom leaves the EU 4. Euro notes and coins enter circulation", "options": ["2-1-3-4", "2-4-1-3", "1-2-4-3", "2-1-4-3"], "answer": 3, "explanation": "Treaty of Rome 1957; Maastricht Treaty in force 1993; euro cash 2002; Brexit on 31 January 2020.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-70", "question": "How many of these statements about the UN General Assembly are correct? I. Each member state has one vote. II. Decisions on important questions need a two-thirds majority of members present and voting. III. Its resolutions are legally binding on all members. IV. Its President is elected for a two-year term.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. General Assembly resolutions are recommendations (only the Security Council's decisions bind members), and its President serves a one-year session.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-71", "question": "Assertion (A): India is not a member of the Nuclear Suppliers Group. Reason (R): India has not signed the Nuclear Non-Proliferation Treaty.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true, and R explains A: India's bid (since 2016) has been blocked mainly by China and a few others on the ground that NSG members should be NPT parties.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-72", "question": "Assertion (A): The WTO's Appellate Body has been unable to hear appeals since December 2019. Reason (R): The WTO Ministerial Conference must meet at least once every two years.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true, but R does not explain A. The Appellate Body stopped working because the United States blocked the appointment of new members, leaving it without a quorum.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-73", "question": "Match the grouping with its members: A. IBSA B. BASIC C. RIC D. I2U2 — 1. Russia, India, China 2. India, Israel, UAE, USA 3. India, Brazil, South Africa 4. Brazil, South Africa, India, China", "options": ["A-3, B-4, C-1, D-2", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-2, D-1"], "answer": 0, "explanation": "IBSA (2003) – India, Brazil, South Africa; BASIC (climate bloc, 2009) – Brazil, South Africa, India, China; RIC – Russia, India, China; I2U2 (2021–22) – India, Israel, UAE, USA.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-74", "question": "How many of these statements about the Shanghai Cooperation Organisation are correct? I. It was founded in 2001 in Shanghai. II. Iran became a full member in 2023. III. Belarus became a full member in 2024. IV. Its official languages are Russian and Chinese.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Iran joined at the July 2023 summit hosted virtually by India, and Belarus at the Astana summit in July 2024.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-75", "question": "Which one of the following is NOT a member of the G20?", "options": ["Argentina", "Saudi Arabia", "Spain", "Turkey"], "answer": 2, "explanation": "Spain attends every G20 summit as a permanent guest but is not a member. The G20 has 19 countries plus the European Union and the African Union.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-76", "question": "Match the UN Secretary-General with his country: A. Kofi Annan B. Ban Ki-moon C. Boutros Boutros-Ghali D. Javier Pérez de Cuéllar — 1. Peru 2. Egypt 3. South Korea 4. Ghana", "options": ["A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1"], "answer": 1, "explanation": "Annan – Ghana (1997–2006); Ban Ki-moon – South Korea (2007–16); Boutros-Ghali – Egypt (1992–96); Pérez de Cuéllar – Peru (1982–91).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-international-orgs-77", "question": "Arrange these UN Secretaries-General by the start of their term: 1. U Thant 2. Kurt Waldheim 3. Dag Hammarskjöld 4. António Guterres", "options": ["3-1-2-4", "1-3-2-4", "3-2-1-4", "3-1-4-2"], "answer": 0, "explanation": "Hammarskjöld 1953; U Thant 1961 (after Hammarskjöld died in an air crash); Waldheim 1972; Guterres 2017.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"gk-international-orgs-78","question":"How many of these statements about the World Bank Group are correct? I. The IFC lends to and invests in the private sector. II. MIGA provides facilities for settling investment disputes. III. ICSID insures investors against political risk. IV. The President of the World Bank has traditionally been a European.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. The roles of II and III are swapped: MIGA insures investors against political risk and ICSID settles investment disputes. By convention the World Bank President is an American and the IMF head a European.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id": "gk-international-orgs-79", "question": "Assertion (A): The United States has an effective veto over major decisions of the IMF. Reason (R): Such decisions need an 85% majority of votes, and the US holds more than 15% of the voting power.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: with about 16.5% of the votes, the US alone can block any decision that needs 85%.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-80", "question": "Match the organisation with the city of its headquarters: A. APEC B. Gulf Cooperation Council C. Organization of American States D. Arab League — 1. Cairo 2. Washington, D.C. 3. Riyadh 4. Singapore", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1", "A-4, B-1, C-2, D-3"], "answer": 2, "explanation": "APEC secretariat – Singapore; GCC – Riyadh; OAS – Washington, D.C.; Arab League – Cairo.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-81", "question": "Which one of the following countries is NOT a member of the Indian Ocean Rim Association?", "options": ["Pakistan", "Mauritius", "Bangladesh", "Sri Lanka"], "answer": 0, "explanation": "Pakistan is not an IORA member (its application has been blocked). IORA's 23 members include India, Australia, South Africa, Iran, the UAE, France and Bangladesh.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-82", "question": "How many of these statements are correct? I. The International Criminal Court was set up under the Rome Statute, which came into force in 2002. II. The ICC is a principal organ of the United Nations. III. India is not a party to the Rome Statute. IV. The International Court of Justice settles legal disputes between states.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. The ICC is an independent treaty body at The Hague, not a UN organ; the ICJ is the UN's principal judicial organ.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-83", "question": "Assertion (A): The G7 became the G8 in 1997 with the admission of China. Reason (R): Russia was suspended from the G8 in 2014 after it annexed Crimea.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 3, "explanation": "A is false: the G8 was formed with Russia, not China (formally from 1997–98). R is true: Russia was suspended in 2014, and the group reverted to the G7.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-84", "question": "Arrange in chronological order: 1. India becomes a full member of the SCO 2. First BRIC summit 3. First G20 leaders' summit 4. African Union joins the G20", "options": ["3-2-1-4", "2-3-1-4", "3-1-2-4", "3-2-4-1"], "answer": 0, "explanation": "First G20 leaders' summit, Washington, November 2008; first BRIC summit, Yekaterinburg, June 2009; India joined the SCO in 2017; the African Union joined the G20 in 2023.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-85", "question": "Match the body with its work: A. IRENA B. IPCC C. IEA D. IUCN — 1. Publishes the Red List of threatened species 2. Promotes renewable energy, from its seat in Abu Dhabi 3. Assesses the science of climate change 4. Works on energy security, from its seat in Paris", "options": ["A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-2, B-4, C-3, D-1", "A-2, B-3, C-4, D-1"], "answer": 3, "explanation": "IRENA – renewable energy (Abu Dhabi); IPCC – climate science assessments (with UNEP and WMO); IEA – energy security (Paris, set up after the 1973 oil crisis); IUCN – Red List (Gland).", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-86", "question": "The United Nations came into existence in the year:", "options": ["1919", "1945", "1948", "1950"], "answer": 1, "explanation": "The UN was founded in 1945 after the Second World War, replacing the League of Nations, which had been set up in 1919–20.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-87", "question": "The World Bank has its headquarters in:", "options": ["New York", "Geneva", "London", "Washington, D.C."], "answer": 3, "explanation": "Both the World Bank and the IMF, the Bretton Woods twins, are based in Washington, D.C. The UN itself is headquartered in New York.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-88", "question": "The secretariat of the UN Framework Convention on Climate Change (UNFCCC) is located in:", "options": ["Bonn", "Nairobi", "Geneva", "Paris"], "answer": 0, "explanation": "The UNFCCC secretariat is in Bonn, Germany. Nairobi hosts UNEP, and the Paris Agreement is named after the city of COP21, not the secretariat's seat.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "gk-international-orgs-89", "question": "The United Nations Environment Programme (UNEP) has its headquarters in:", "options": ["Rome", "Nairobi", "Vienna", "Bangkok"], "answer": 1, "explanation": "UNEP, set up after the 1972 Stockholm Conference, is based in Nairobi, Kenya, making it one of the few UN bodies headquartered in the global South.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "gk-international-orgs-90", "question": "The International Atomic Energy Agency (IAEA), which promotes peaceful use of nuclear energy and inspects nuclear facilities, is based in:", "options": ["Geneva", "The Hague", "Vienna", "Brussels"], "answer": 2, "explanation": "The IAEA, founded in 1957, is in Vienna. The Hague hosts the International Court of Justice and the chemical-weapons watchdog OPCW.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "gk-international-orgs-91", "question": "Which UN agency is unique in being tripartite, with governments, employers and workers all represented in its decision-making?", "options": ["World Health Organization", "UNESCO", "World Bank", "International Labour Organization"], "answer": 3, "explanation": "The ILO, founded in 1919 and based in Geneva, gives employers' and workers' delegates a vote alongside governments when adopting labour conventions.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-92", "question": "The UN agency mandated to protect refugees and stateless people is the:", "options": ["UNHCR, headquartered in Geneva", "UNICEF, headquartered in New York", "UNDP, headquartered in New York", "IOM, headquartered in Vienna"], "answer": 0, "explanation": "The Office of the UN High Commissioner for Refugees, set up in 1950, works from Geneva. UNICEF serves children and UNDP development; the IOM, a related migration body, is also in Geneva.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-93", "question": "The World Meteorological Organization, the UN agency for weather, climate and water, is headquartered in:", "options": ["Washington, D.C.", "Geneva", "Tokyo", "Rome"], "answer": 1, "explanation": "The WMO is in Geneva. Together with UNEP it set up the Intergovernmental Panel on Climate Change (IPCC) in 1988.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-94", "question": "The UN Charter was signed at San Francisco on 26 June 1945. The UN formally came into existence on 24 October 1945 because on that date:", "options": ["The first General Assembly met", "The first Secretary-General took office", "The Charter came into force after ratification by the five permanent members and a majority of the other signatories", "The UN headquarters building opened"], "answer": 2, "explanation": "Ratification by China, France, the USSR, the UK, the US and most other signatories brought the Charter into force on 24 October, now UN Day. The first General Assembly met in London in January 1946.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-95", "question": "CITES is an international agreement that regulates:", "options": ["International trade in endangered species of wild animals and plants", "Emissions of greenhouse gases", "Trade in hazardous waste", "Use of ozone-depleting substances"], "answer": 0, "explanation": "The Convention on International Trade in Endangered Species (1973) lists species in appendices that restrict trade. Hazardous waste falls under the Basel Convention and ozone depletion under the Montreal Protocol.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-96", "question": "Match the organisation with its headquarters. A. OPCW  B. UN Tourism (UNWTO)  C. ITU  D. International Seabed Authority; 1. Kingston, Jamaica  2. Geneva  3. Madrid  4. The Hague", "options": ["A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "The Organisation for the Prohibition of Chemical Weapons is at The Hague; UN Tourism in Madrid; the International Telecommunication Union, among the oldest international bodies, in Geneva; the Seabed Authority, set up under UNCLOS, in Kingston.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id":"gk-international-orgs-97","question":"How many of these statements are correct? I. The UN Economic and Social Council (ECOSOC) has 54 members. II. ECOSOC members are elected by the General Assembly for three-year terms. III. The Trusteeship Council suspended its operations in 1994 after the last trust territory, Palau, became independent. IV. ECOSOC can grant consultative status to non-governmental organisations.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. ECOSOC has 54 members elected by the General Assembly for three-year terms and, under Article 71 of the Charter, grants consultative status to NGOs; the Trusteeship Council suspended work in 1994 after Palau’s independence.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id": "gk-international-orgs-98", "question": "Assertion (A): Decisions of the UN Security Council can be binding on all UN member states. Reason (R): Under Article 25 of the UN Charter, members agree to accept and carry out the decisions of the Security Council.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Article 25, together with enforcement powers under Chapter VII, makes Security Council decisions binding, unlike General Assembly resolutions, which are recommendations.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-99", "question": "Arrange these organisations in the order they were founded: 1. International Labour Organization  2. International Monetary Fund  3. World Trade Organization  4. NATO", "options": ["1-4-2-3", "1-2-4-3", "2-1-4-3", "1-2-3-4"], "answer": 1, "explanation": "The ILO dates from 1919, the IMF from 1945 (agreed at Bretton Woods in 1944), NATO from 1949 and the WTO from 1995.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-100", "question": "How many of these statements about the Paris Agreement are correct? I. It was adopted at COP21 in 2015. II. It aims to keep global warming well below 2 °C and to pursue efforts to limit it to 1.5 °C. III. Each country sets its own targets through Nationally Determined Contributions (NDCs). IV. The emission targets in NDCs are legally binding, with financial penalties for missing them.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "I, II and III are correct. Countries are bound to prepare, report and update NDCs, but meeting the targets is not legally enforceable and there are no penalties, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-international-orgs-101", "question": "The flag of the United Nations shows a map of the world surrounded by:", "options": ["Two olive branches", "A ring of twelve stars", "Five interlocking rings", "A laurel crown and a dove"], "answer": 0, "explanation": "The UN emblem is a world map centred on the North Pole, framed by olive branches as a symbol of peace. Twelve stars are on the EU flag and five rings on the Olympic flag.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-102", "question": "How many articles does the Charter of the United Nations contain?", "options": ["100", "111", "70", "125"], "answer": 1, "explanation": "The UN Charter has 111 articles in 19 chapters, and the Statute of the International Court of Justice is annexed to it.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-103", "question": "FIFA, the world governing body of football, has its headquarters in:", "options": ["Paris", "Lausanne", "Zurich", "Geneva"], "answer": 2, "explanation": "FIFA is based in Zurich. Lausanne hosts the International Olympic Committee, and FIFA was founded in Paris in 1904.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-104", "question": "Match the convention with its subject. A. Basel Convention  B. Rotterdam Convention  C. Stockholm Convention  D. Minamata Convention; 1. Mercury  2. Persistent organic pollutants  3. Prior informed consent for trade in hazardous chemicals and pesticides  4. Transboundary movement of hazardous wastes", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Basel (1989) controls cross-border movement of hazardous waste; Rotterdam (1998) sets prior informed consent for trade in hazardous chemicals; Stockholm (2001) targets persistent organic pollutants; Minamata (2013), named after the Japanese mercury disaster, covers mercury.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-105", "question": "The International Olympic Committee (IOC) is headquartered in:", "options": ["Lausanne", "Geneva", "Athens", "Zurich"], "answer": 0, "explanation": "The IOC has been based in Lausanne, Switzerland, since 1915. Athens hosted the first modern Games, and Zurich is FIFA's home.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-106", "question": "Who was the first Secretary-General of the United Nations?", "options": ["Dag Hammarskjöld", "Trygve Lie", "U Thant", "Gladwyn Jebb"], "answer": 1, "explanation": "Trygve Lie of Norway served from 1946 to 1952. Gladwyn Jebb was only acting Secretary-General in 1945–46, and Hammarskjöld succeeded Lie.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-107", "question": "The Commonwealth of Independent States (CIS) was formed in 1991 following the:", "options": ["End of British rule in Hong Kong", "Breakup of Yugoslavia", "Dissolution of the Soviet Union", "Reunification of Germany"], "answer": 2, "explanation": "The CIS was created in December 1991 by former Soviet republics as the USSR dissolved. It has nothing to do with the British Commonwealth of Nations.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "gk-international-orgs-108", "question": "Arrange in chronological order: 1. First summit of the Non-Aligned Movement  2. UN Conference on the Human Environment at Stockholm  3. Asian–African Conference at Bandung  4. Formation of the Group of 77", "options": ["3-1-2-4", "1-3-4-2", "3-4-1-2", "3-1-4-2"], "answer": 3, "explanation": "Bandung was held in 1955, the first NAM summit at Belgrade in 1961, the G77 was formed at the end of the first UNCTAD in 1964, and the Stockholm Conference took place in 1972.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-109", "question": "Who was the first woman to be elected President of the UN General Assembly?", "options": ["Vijaya Lakshmi Pandit", "Eleanor Roosevelt", "Indira Gandhi", "Hansa Mehta"], "answer": 0, "explanation": "India's Vijaya Lakshmi Pandit presided over the eighth session in 1953. Eleanor Roosevelt chaired the Commission on Human Rights, and Hansa Mehta helped draft the Universal Declaration of Human Rights.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-110", "question": "The World Economic Forum holds its well-known annual meeting of political and business leaders at:", "options": ["Geneva", "Davos", "Vienna", "Brussels"], "answer": 1, "explanation": "The annual meeting is held at Davos, a Swiss ski resort. The Forum's own headquarters is at Cologny, near Geneva.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id":"gk-international-orgs-111","question":"How many of these statements about the Universal Declaration of Human Rights are correct? I. It was adopted by the UN General Assembly on 10 December 1948. II. It was adopted at a session held in Paris. III. Hansa Mehta of India helped change its wording from 'all men' to 'all human beings'. IV. Eleanor Roosevelt chaired the UN Commission on Human Rights that drafted it.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The UDHR was adopted in Paris on 10 December 1948 (now Human Rights Day), Eleanor Roosevelt chaired the drafting Commission, and India’s Hansa Mehta is credited with changing 'all men are born free and equal' to 'all human beings'.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-112", "question": "The Kyoto Protocol, which set binding emission-reduction targets for developed countries, was adopted at:", "options": ["COP15 in 2009", "The Rio Earth Summit in 1992", "COP21 in 2015", "COP3 in 1997"], "answer": 3, "explanation": "The Kyoto Protocol was adopted at COP3 in Kyoto in 1997 and came into force in 2005. The UNFCCC itself was opened for signature at Rio in 1992, and the Paris Agreement came at COP21.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-international-orgs-113", "question": "When UNICEF was set up in 1946, its name stood for:", "options": ["United Nations International Children's Emergency Fund", "United Nations Initiative for Children's Education Fund", "United Nations International Child Education Forum", "Universal Network for International Child Care and Education"], "answer": 0, "explanation": "UNICEF began as the United Nations International Children's Emergency Fund to help children after the Second World War. In 1953 it became the United Nations Children's Fund but kept the acronym.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-114", "question": "Under the UN Convention on the Law of the Sea (UNCLOS), a coastal state's territorial sea may extend up to:", "options": ["24 nautical miles", "12 nautical miles", "200 nautical miles", "350 nautical miles"], "answer": 1, "explanation": "The territorial sea extends 12 nautical miles from the baseline. The contiguous zone reaches 24 nautical miles and the exclusive economic zone 200 nautical miles.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-115", "question": "Assertion (A): The Kigali Amendment (2016) to the Montreal Protocol provides for phasing down hydrofluorocarbons (HFCs). Reason (R): HFCs are major ozone-depleting substances.", "options": ["Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true. HFCs replaced ozone-depleting CFCs and HCFCs and do not harm the ozone layer; they were targeted because they are very powerful greenhouse gases, so R is false.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-116", "question": "Médecins Sans Frontières (Doctors Without Borders), winner of the 1999 Nobel Peace Prize, was founded in 1971 in:", "options": ["The Netherlands", "Switzerland", "Belgium", "France"], "answer": 3, "explanation": "MSF was founded in Paris in 1971 by doctors and journalists. Switzerland is home to the separate International Committee of the Red Cross.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-international-orgs-117", "question": "Where is the official seat of the European Parliament, where most of its plenary sessions are held?", "options": ["Strasbourg", "Brussels", "Luxembourg", "The Hague"], "answer": 0, "explanation": "Under the EU treaties the Parliament's official seat is Strasbourg. Its committees meet in Brussels and its secretariat is in Luxembourg.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-international-orgs-118", "question": "How many of these statements about NATO are correct? I. It was founded in 1949. II. Its founding treaty was signed in Brussels. III. France left NATO's integrated military command in 1966 and returned in 2009. IV. Sweden became a member before Finland.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. The North Atlantic Treaty was signed in Washington, D.C. (Brussels is the present headquarters), and Finland joined in April 2023, before Sweden in March 2024, so II and IV are wrong.", "difficulty": "very-hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-international-orgs-119", "question": "The Colombo Plan, which began in 1951 to promote economic and social development in Asia and the Pacific, originated at a meeting of:", "options": ["ASEAN foreign ministers", "Non-Aligned Movement leaders", "Commonwealth foreign ministers", "UN Economic Commission for Asia and the Far East members"], "answer": 2, "explanation": "The plan was conceived at the Commonwealth Foreign Ministers' meeting in Colombo in January 1950. ASEAN did not exist until 1967 and NAM until 1961.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-120", "question": "Greenpeace International, the environmental campaigning organisation, is headquartered in:", "options": ["Vancouver", "Gland", "Nairobi", "Amsterdam"], "answer": 3, "explanation": "Greenpeace International is based in Amsterdam, although Greenpeace began in Vancouver in 1971. Gland, Switzerland, hosts WWF and IUCN.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id":"gk-international-orgs-121","question":"How many of these statements about the Antarctic Treaty are correct? I. It was signed in Geneva in 1959. II. It allows Antarctica to be used for peaceful purposes only. III. India acceded to it in 1981. IV. It divided Antarctica among the countries that had claimed territory there.","options":["Only three","Only two","Only one","All four"],"answer":2,"explanation":"Only II is correct. The treaty was signed in Washington in 1959; India acceded in 1983 (its first expedition went in 1981); and the treaty froze existing territorial claims rather than dividing the continent.","difficulty":"very-hard","source":"UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-122", "question": "The World Heritage Convention, under which sites are placed on the World Heritage List, was adopted by UNESCO in:", "options": ["1945", "1972", "1965", "1992"], "answer": 1, "explanation": "UNESCO's General Conference adopted the Convention concerning the Protection of the World Cultural and Natural Heritage in Paris in November 1972. UNESCO itself was founded in 1945.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-international-orgs-123", "question": "Match the agreement with its subject. A. Ramsar Convention  B. Bonn Convention  C. Vienna Convention (1985)  D. Cartagena Protocol; 1. Biosafety of living modified organisms  2. Protection of the ozone layer  3. Migratory species of wild animals  4. Wetlands of international importance", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1"], "answer": 2, "explanation": "Ramsar (1971) protects wetlands; the Bonn Convention (CMS, 1979) covers migratory species; the 1985 Vienna Convention is the framework for ozone protection that the Montreal Protocol implements; the Cartagena Protocol under the CBD deals with biosafety.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-international-orgs-124", "question": "The Organisation of Islamic Cooperation (OIC), founded in 1969, has its general secretariat in:", "options": ["Rabat", "Riyadh", "Cairo", "Jeddah"], "answer": 3, "explanation": "The OIC secretariat is in Jeddah, Saudi Arabia. The organisation was founded at a summit in Rabat; Cairo hosts the Arab League.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-international-orgs-125", "question": "How many of these UN bodies are correctly matched with their headquarters? I. World Food Programme — Rome  II. UN Population Fund (UNFPA) — Nairobi  III. UN Women — Geneva  IV. International Organization for Migration — Geneva", "options": ["Only two", "Only one", "Only three", "All four"], "answer": 0, "explanation": "I and IV are correct. Both UNFPA and UN Women are headquartered in New York, so II and III are wrong. Nairobi hosts UNEP and UN-Habitat.", "difficulty": "very-hard", "source": "SSC CGL · State PSC"},
  {"id":"gk-international-orgs-126","question":"Under which Chapter of the UN Charter can the Security Council decide on sanctions and military action against a threat to the peace, breach of the peace or act of aggression?","options":["Chapter VI","Chapter VII","Chapter VIII","Chapter XII"],"answer":1,"explanation":"Chapter VII (Articles 39–51) gives the Council enforcement powers. Chapter VI covers pacific settlement of disputes, Chapter VIII regional arrangements and Chapter XII the trusteeship system.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-127","question":"Which Article of the UN Charter preserves a member state's 'inherent right' of individual or collective self-defence if an armed attack occurs, until the Security Council has taken the necessary measures?","options":["Article 2(4)","Article 39","Article 51","Article 99"],"answer":2,"explanation":"Article 51 is the self-defence clause. Article 2(4) prohibits the threat or use of force, Article 39 lets the Council determine a threat to peace, and Article 99 lets the Secretary-General bring matters to the Council.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-128","question":"Under Article 19 of the UN Charter, a member whose arrears equal or exceed the contributions due from it for the preceding two full years loses its vote in:","options":["The Security Council","The Economic and Social Council","Every principal organ of the UN","The General Assembly"],"answer":3,"explanation":"Article 19 suspends the defaulting member's vote in the General Assembly only, unless the Assembly decides the failure was beyond the member's control.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-international-orgs-129","question":"How many of these statements about amending the UN Charter under Article 108 are correct? I. An amendment must be adopted by a two-thirds vote of the Security Council. II. It must then be ratified by three-fourths of the UN members. III. The ratifying members must include all five permanent members of the Security Council. IV. The Charter has never been amended since 1945.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. Under Article 108 an amendment needs a two-thirds vote of the General Assembly (not the Security Council) and ratification by two-thirds of members, including all five permanent members. The Charter has been amended, e.g. in 1965 to enlarge the Security Council.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-130","question":"The amendment to the UN Charter that came into force in 1965 changed the number of non-permanent members of the Security Council from:","options":["4 to 8","6 to 10","5 to 10","6 to 9"],"answer":1,"explanation":"The Council grew from 11 members (5 permanent + 6 elected) to 15 (5 + 10). The same 1965 amendments raised ECOSOC from 18 to 27 members.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-131","question":"The 'Uniting for Peace' resolution (377 A), adopted in 1950 during the Korean War, provides that:","options":["The Security Council may override a single permanent member's veto by a two-thirds vote when peace is threatened","The Secretary-General may send peacekeepers without Council approval while an armed attack continues","Regional organisations may use force against an aggressor once the General Assembly condemns it","The General Assembly may take up a threat to peace if a lack of permanent-member unanimity blocks the Council"],"answer":3,"explanation":"Resolution 377 A lets the General Assembly consider the matter and recommend collective measures when a veto blocks the Council. It does not override the veto in the Council itself.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-132","question":"The name 'United Nations', first used officially in the Declaration by United Nations of 1 January 1942, was coined by:","options":["Franklin D. Roosevelt","Winston Churchill","Field Marshal Jan Smuts","Cordell Hull"],"answer":0,"explanation":"US President Franklin D. Roosevelt devised the name; it appeared in the 1942 Declaration in which the Allied nations pledged to fight the Axis together.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-133","question":"The first detailed proposals for the structure of the future United Nations, including a Security Council, were drawn up in 1944 at:","options":["Yalta","San Francisco","Dumbarton Oaks","Tehran"],"answer":2,"explanation":"The Dumbarton Oaks Conference (Washington, 1944) drafted the outline. Yalta (February 1945) settled the Council voting formula and San Francisco (1945) adopted the Charter.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-international-orgs-134","question":"Arrange in chronological order: 1. Yalta Conference  2. Atlantic Charter  3. Dumbarton Oaks Conference  4. Declaration by United Nations","options":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"answer":0,"explanation":"Atlantic Charter (August 1941), Declaration by United Nations (January 1942), Dumbarton Oaks (August–October 1944), Yalta (February 1945).","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-135","question":"Match the Main Committee of the UN General Assembly with its subject. A. First Committee  B. Third Committee  C. Fourth Committee  D. Sixth Committee; 1. Social, humanitarian and cultural  2. Legal  3. Disarmament and international security  4. Special political and decolonisation","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4"],"answer":1,"explanation":"First: disarmament and security; Second: economic and financial; Third: social, humanitarian and cultural; Fourth: special political and decolonisation; Fifth: administrative and budgetary; Sixth: legal.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-136","question":"Match the UN regional commission with its headquarters. A. ESCAP  B. ECA  C. ECLAC  D. ESCWA; 1. Santiago  2. Beirut  3. Bangkok  4. Addis Ababa","options":["A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"ESCAP (Asia-Pacific) sits in Bangkok, ECA (Africa) in Addis Ababa, ECLAC (Latin America and the Caribbean) in Santiago and ESCWA (Western Asia) in Beirut; ECE is in Geneva.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-137","question":"The presidency of the UN Security Council rotates:","options":["Every month, following the order in which members were elected to it","Every three months, among the five permanent members only","Every month, in the English alphabetical order of member states' names","Every year, through an election held among all fifteen Council members"],"answer":2,"explanation":"Under the Council's rules of procedure the presidency passes each month to the next member in English alphabetical order, so permanent and elected members both hold it.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-138","question":"Chinese, English, French, Russian and Spanish were the UN's official languages from the start. Which language was added as an official language of the General Assembly in 1973?","options":["German","Hindi","Japanese","Arabic"],"answer":3,"explanation":"Arabic was added in 1973, giving the UN six official languages. Spanish, sometimes assumed to be a later addition, was official from 1946.","difficulty":"hard","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-139","question":"General Assembly Resolution 2758, adopted in 1971, provided that:","options":["Both Chinese governments would be seated as separate members, with the permanent veto staying with Taipei","The Republic of China would keep its Assembly seat but give up its Security Council seat","China's permanent seat would be suspended until the two governments agreed on representation","The People's Republic of China would take China's seat, including its permanent seat on the Council"],"answer":3,"explanation":"Resolution 2758 recognised the PRC's representatives as the only lawful representatives of China, so Beijing replaced Taipei in all UN organs, including the permanent Security Council seat.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-140","question":"The UN Trusteeship Council suspended its operations in 1994 after the last trust territory gained independence. That territory was:","options":["Palau","Namibia","Nauru","Papua New Guinea"],"answer":0,"explanation":"Palau, part of the Trust Territory of the Pacific Islands, became independent in 1994. Namibia was a League mandate held by South Africa, not a UN trust territory.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-141","question":"How many of these statements are correct? I. UNTSO, set up in 1948 to observe the truce in Palestine, was the first UN peacekeeping operation. II. UNEF I, sent during the Suez Crisis of 1956, was the first armed UN peacekeeping force. III. UN Peacekeeping Forces received the Nobel Peace Prize in 1988. IV. UNMOGIP, which observes the ceasefire in Jammu and Kashmir, was set up in 1949.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. UNTSO (1948) was an unarmed observer mission; UNEF I (1956) was the first armed force; the 1988 Nobel went to UN peacekeepers; UNMOGIP's observers arrived in 1949.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-142","question":"India took the Jammu and Kashmir question to the UN Security Council on 1 January 1948 under which Article of the Charter, which lets a member bring a dispute to the Council's attention?","options":["Article 35","Article 39","Article 51","Article 2(7)"],"answer":0,"explanation":"India complained under Article 35, part of Chapter VI on pacific settlement, so the Council could only recommend. Article 39 opens Chapter VII enforcement and Article 2(7) protects domestic jurisdiction.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-143","question":"Which organisation has won the Nobel Peace Prize three times, in 1917, 1944 and 1963?","options":["International Committee of the Red Cross","Office of the UN High Commissioner for Refugees","International Labour Organization","United Nations Children's Fund"],"answer":0,"explanation":"The ICRC won in 1917, 1944 and 1963 (the last shared with the League of Red Cross Societies). UNHCR won twice (1954, 1981); the ILO (1969) and UNICEF (1965) once each.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-144","question":"Match the organisation with the year it won the Nobel Peace Prize. A. UNICEF  B. International Labour Organization  C. International Atomic Energy Agency  D. World Food Programme; 1. 2020  2. 1965  3. 2005  4. 1969","options":["A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":2,"explanation":"UNICEF won in 1965, the ILO in 1969 (its 50th year), the IAEA in 2005 (with Mohamed ElBaradei) and the WFP in 2020.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-international-orgs-145","question":"The WHO Regional Office for South-East Asia, whose region includes India, is located in:","options":["Manila","Kathmandu","New Delhi","Cairo"],"answer":2,"explanation":"The South-East Asia Regional Office is in New Delhi. Manila hosts the Western Pacific office and Cairo the Eastern Mediterranean office.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-146","question":"World Health Day is observed on 7 April because on that date in 1948:","options":["The first World Health Assembly opened in Geneva","WHO's constitution came into force","WHO declared the worldwide eradication of smallpox","The Alma-Ata Declaration on primary health care was adopted"],"answer":1,"explanation":"WHO's constitution entered into force on 7 April 1948. The first World Health Assembly met in June 1948, smallpox eradication was declared in 1980 and Alma-Ata was in 1978.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-147","question":"Match the day with its date. A. World Food Day  B. World Meteorological Day  C. World Post Day  D. World Telecommunication and Information Society Day; 1. 9 October  2. 17 May  3. 16 October  4. 23 March","options":["A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2","A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Each marks a founding: FAO on 16 October 1945, the WMO Convention on 23 March 1950, the UPU on 9 October 1874 and the ITU on 17 May 1865.","difficulty":"very-hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-148","question":"Judges of the International Court of Justice are elected by:","options":["The General Assembly alone, by a two-thirds majority of members present and voting","Both the General Assembly and the Security Council, with an absolute majority in each","The Security Council on the Secretary-General's recommendation, with the veto applying","The states parties to the ICJ Statute, voting at a special conference held in The Hague"],"answer":1,"explanation":"Under the ICJ Statute both organs vote independently and a candidate needs an absolute majority in each; the permanent members' veto does not apply to this vote.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-149","question":"Assertion (A): The International Court of Justice can decide a contentious case between two states only if both have accepted its jurisdiction. Reason (R): Only states, not individuals or companies, can be parties to contentious cases before the ICJ.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but jurisdiction rests on state consent (special agreement, treaty clause or optional-clause declaration); the rule that only states may be parties is a separate limit.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-150","question":"The International Court of Justice replaced which court that had been set up under the League of Nations system?","options":["Permanent Court of International Justice","Permanent Court of Arbitration","International Criminal Court","International Tribunal for the Law of the Sea"],"answer":0,"explanation":"The PCIJ (1922) was succeeded by the ICJ in 1946. The Permanent Court of Arbitration (1899) still exists separately, also at The Hague.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-151","question":"The constitution of the International Labour Organization, founded in 1919, was originally contained in:","options":["The Declaration of Philadelphia","The Atlantic Charter","Part XIII of the Treaty of Versailles","A resolution of the League of Nations Assembly"],"answer":2,"explanation":"The ILO's constitution formed Part XIII of the Treaty of Versailles (1919). The Declaration of Philadelphia (1944) restated its aims and was later annexed to the constitution.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-152","question":"Arrange these World Bank Group institutions in the order they were established: 1. International Development Association  2. Multilateral Investment Guarantee Agency  3. International Finance Corporation  4. International Centre for Settlement of Investment Disputes","options":["1-3-4-2","3-1-2-4","3-1-4-2","3-4-1-2"],"answer":2,"explanation":"IFC (1956), IDA (1960), ICSID (1966), MIGA (1988); the IBRD itself dates from 1944.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-153","question":"India is a member of four of the five World Bank Group institutions. Which one has India NOT joined?","options":["International Finance Corporation","International Development Association","Multilateral Investment Guarantee Agency","International Centre for Settlement of Investment Disputes"],"answer":3,"explanation":"India has not signed the ICSID Convention, so it is outside the Centre that arbitrates investor–state disputes; it is a member of the IBRD, IDA, IFC and MIGA.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-154","question":"The World Bank (IBRD) made its first loan, of 250 million dollars for post-war reconstruction, in 1947 to:","options":["India","France","The Netherlands","Chile"],"answer":1,"explanation":"France received the first IBRD loan in May 1947. Reconstruction of war-hit Europe was the Bank's first task before it turned mainly to development.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-155","question":"The IMF created the Special Drawing Right (SDR) in 1969 in order to:","options":["Replace the US dollar as the anchor of the gold-exchange system","Supplement the official reserves held by member countries","Fund concessional loans to the poorest member countries","Settle trade payments between firms in different countries"],"answer":1,"explanation":"The SDR is an international reserve asset allocated to members to add to their official reserves; it is not a currency used by private firms and did not itself replace the dollar.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"gk-international-orgs-156","question":"How many of these statements are correct? I. IMF quotas are expressed in US dollars and largely decide a member's voting power. II. India was a founding member of both the IMF and the IBRD. III. The IMF's Articles of Agreement came into force in July 1944. IV. The IMF lends mainly for long-term infrastructure projects.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. IMF quotas are expressed in Special Drawing Rights (SDRs), not dollars; July 1944 was the Bretton Woods conference, while the Articles came into force in December 1945; and long-term project lending is the World Bank's role.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"gk-international-orgs-157","question":"The General Agreement on Tariffs and Trade (GATT) was signed in 1947 at:","options":["Havana","Bretton Woods","Marrakesh","Geneva"],"answer":3,"explanation":"GATT was signed at Geneva in October 1947 by 23 countries, India among them. The Havana Charter (1948) for an International Trade Organization was never ratified.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-international-orgs-158","question":"Arrange these GATT/WTO trade rounds in chronological order of launch: 1. Uruguay Round  2. Kennedy Round  3. Tokyo Round  4. Doha Round","options":["2-3-1-4","3-2-1-4","2-1-3-4","2-3-4-1"],"answer":0,"explanation":"Kennedy (1964), Tokyo (1973), Uruguay (1986) and Doha (2001).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-159","question":"The Uruguay Round of GATT negotiations, which led to the WTO, was launched in 1986 at:","options":["Montevideo","Punta del Este","Marrakesh","Doha"],"answer":1,"explanation":"Ministers launched the round at Punta del Este, Uruguay, in September 1986; it ended with the Marrakesh Agreement of 1994.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-160","question":"Match the WTO agriculture category with what it covers. A. Amber box  B. Blue box  C. Green box  D. De minimis; 1. Support causing no or minimal trade distortion  2. Trade-distorting support subject to reduction commitments  3. Direct payments tied to production-limiting programmes  4. Small trade-distorting support allowed up to a set share of output value","options":["A-2, B-1, C-3, D-4","A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Amber box support (e.g. price support) must be cut; blue box payments come with production limits; green box support is permitted without limits; de minimis allows small amber support (10% for most developing countries).","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-161","question":"The 'peace clause' agreed at the WTO's Bali Ministerial Conference in 2013, important to India, shields developing countries from legal challenge over:","options":["Compulsory licensing of patented medicines in health emergencies","Export bans on food grains during domestic shortages","Public stockholding of food grains for food security","Fuel subsidies given to fishing fleets within their EEZ"],"answer":2,"explanation":"The interim peace clause protects public stockholding programmes (such as India's grain procurement at minimum support prices) from disputes even if they breach subsidy limits.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-162","question":"Which agreement, adopted at the WTO's Bali Ministerial Conference in 2013, is described as the first multilateral agreement concluded since the WTO was set up?","options":["Trade Facilitation Agreement","Information Technology Agreement","Agreement on Agriculture","Agreement on Fisheries Subsidies"],"answer":0,"explanation":"The Trade Facilitation Agreement eases customs procedures; it came into force in 2017. The ITA (1996) is plurilateral, the Agreement on Agriculture is a Uruguay Round text and the fisheries deal came in 2022.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-163","question":"How many of these statements about the WTO are correct? I. The Doha Development Agenda was launched at the fourth Ministerial Conference in 2001. II. The Doha Declaration on TRIPS and Public Health affirmed members' right to grant compulsory licences. III. The first Ministerial Conference was held in Singapore in 1996. IV. The Nairobi Ministerial Conference of 2015 decided to eliminate agricultural export subsidies.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Singapore (1996) also gave its name to the 'Singapore issues' such as investment and competition policy.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-164","question":"Under GATT, the principle that a trade advantage given to one member must be extended immediately and unconditionally to all members is called:","options":["National treatment","Special and differential treatment","Reciprocity","Most-favoured-nation treatment"],"answer":3,"explanation":"MFN (GATT Article I) bars discrimination between trading partners; national treatment (Article III) bars discrimination between imported and domestic goods.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B"},
  {"id":"gk-international-orgs-165","question":"Match the WTO agreement with its subject. A. TRIPS  B. TRIMs  C. SPS Agreement  D. TBT Agreement; 1. Food safety and animal and plant health measures  2. Technical regulations and product standards  3. Investment measures such as local-content rules  4. Intellectual property rights","options":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"TRIPS covers intellectual property, TRIMs trade-related investment measures, SPS sanitary and phytosanitary measures and TBT technical barriers such as standards and labelling.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-166","question":"The Bank for International Settlements, called the central bank of central banks and founded in 1930, is based at:","options":["Zurich","Geneva","Basel","Frankfurt"],"answer":2,"explanation":"The BIS is in Basel, Switzerland, and hosts the Basel Committee on Banking Supervision, whose norms are known as the Basel accords.","difficulty":"moderate","source":"SSC CGL · RBI Grade B"},
  {"id":"gk-international-orgs-167","question":"The Basel III norms, framed after the 2008 financial crisis, mainly aim to:","options":["Harmonise deposit insurance limits across G20 countries","Strengthen banks' capital, liquidity and leverage standards","Fix interest-rate ceilings on cross-border bank lending","Set one minimum cash reserve ratio for all central banks"],"answer":1,"explanation":"Basel III raised the quality and quantity of bank capital and added a leverage ratio and liquidity ratios (LCR and NSFR); it does not set deposit insurance or reserve ratios.","difficulty":"hard","source":"RBI Grade B · IBPS PO Mains"},
  {"id":"gk-international-orgs-168","question":"The Financial Stability Board, set up by the G20 in 2009 to coordinate financial regulation, replaced the:","options":["Basel Committee on Banking Supervision","Financial Stability Forum","Group of Thirty","Paris Club"],"answer":1,"explanation":"The Financial Stability Forum, created by the G7 in 1999, was turned into the FSB with a broader membership after the 2008 crisis; it is hosted by the BIS in Basel.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"gk-international-orgs-169","question":"The Paris Club is an informal group of:","options":["Commercial banks that renegotiate loans made to sovereign borrowers","Central banks that coordinate intervention in currency markets","Official creditor countries that coordinate debt relief for borrowers","Rich countries that fund the OECD's development assistance work"],"answer":2,"explanation":"The Paris Club brings together official (government) creditors to restructure debts of borrower countries; private bank creditors meet in the London Club.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B"},
  {"id":"gk-international-orgs-170","question":"The OECD (1961) grew out of the OEEC, which was set up in 1948 to:","options":["Run the common market of the European Coal and Steel Community","Administer Marshall Plan aid for the rebuilding of Europe","Coordinate Western European defence against the Soviet bloc","Set a common external tariff for the six founding EEC states"],"answer":1,"explanation":"The Organisation for European Economic Co-operation managed US Marshall Plan aid; in 1961 it became the OECD, with the US and Canada as members, headquartered in Paris.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-171","question":"OPEC was founded at the Baghdad Conference of September 1960 by Iran, Iraq, Kuwait, Saudi Arabia and:","options":["Libya","Qatar","Venezuela","United Arab Emirates"],"answer":2,"explanation":"Venezuela was the fifth founder; Qatar joined in 1961, Libya in 1962 and the UAE (through Abu Dhabi) in 1967.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-172","question":"OPEC is headquartered in Vienna, although Austria is not a member. Where was its secretariat during its first five years, until 1965?","options":["Geneva","Baghdad","Caracas","Kuwait City"],"answer":0,"explanation":"OPEC's secretariat was in Geneva from 1961 and moved to Vienna in 1965 after Switzerland declined to extend diplomatic privileges.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-173","question":"The African Development Bank is headquartered in:","options":["Addis Ababa","Nairobi","Lagos","Abidjan"],"answer":3,"explanation":"The AfDB is based at Abidjan, Côte d'Ivoire. Addis Ababa hosts the African Union and the UN Economic Commission for Africa.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-174","question":"The European Bank for Reconstruction and Development, founded in 1991 to help former communist countries move to market economies, is headquartered in:","options":["London","Frankfurt","Luxembourg","Brussels"],"answer":0,"explanation":"The EBRD is in London. Luxembourg hosts the European Investment Bank and Frankfurt the European Central Bank.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2"},
  {"id":"gk-international-orgs-175","question":"Match the development bank with its headquarters. A. Islamic Development Bank  B. Inter-American Development Bank  C. European Investment Bank  D. New Development Bank; 1. Luxembourg  2. Shanghai  3. Washington, D.C.  4. Jeddah","options":["A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"answer":1,"explanation":"IsDB: Jeddah; IDB: Washington, D.C.; EIB: Luxembourg; NDB (BRICS bank): Shanghai.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-176","question":"The World Customs Organization, which maintains the Harmonized System (HS) for classifying traded goods, is headquartered in:","options":["Geneva","Vienna","Paris","Brussels"],"answer":3,"explanation":"The WCO, founded in 1952 as the Customs Co-operation Council, is based in Brussels; Geneva hosts the WTO.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-177","question":"The Contingent Reserve Arrangement agreed by the BRICS countries at Fortaleza in 2014 is meant to:","options":["Give members liquidity support against short-term balance-of-payments pressure","Finance infrastructure and sustainable development projects in member countries","Launch a common BRICS reserve currency to replace the US dollar in trade","Pool members' gold reserves to back a joint cross-border payments system"],"answer":0,"explanation":"The CRA is a reserve-pooling safety net for balance-of-payments stress; project finance is the job of the New Development Bank set up by the same Fortaleza declaration.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-178","question":"Arrange these countries in the order in which they joined ASEAN: 1. Vietnam  2. Brunei  3. Cambodia  4. Myanmar","options":["2-1-4-3","1-2-4-3","2-1-3-4","2-4-1-3"],"answer":0,"explanation":"Brunei joined in 1984, Vietnam in 1995, Laos and Myanmar in 1997 and Cambodia in 1999.","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-179","question":"ASEAN was established in August 1967 by the:","options":["Manila Declaration","Bali Concord","Bangkok Declaration","Singapore Declaration"],"answer":2,"explanation":"Indonesia, Malaysia, the Philippines, Singapore and Thailand signed the ASEAN (Bangkok) Declaration on 8 August 1967.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-180","question":"The ASEAN Charter, which gave the grouping a legal personality, entered into force in:","options":["1997","2003","2015","2008"],"answer":3,"explanation":"The Charter was signed in 2007 and came into force in December 2008. The ASEAN Community was formally launched later, at the end of 2015.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-181","question":"The first East Asia Summit, in which India took part as a founding participant, was held in 2005 at:","options":["Bandar Seri Begawan","Kuala Lumpur","Cebu","Jakarta"],"answer":1,"explanation":"The first EAS met in Kuala Lumpur in December 2005 with the ten ASEAN states, China, Japan, South Korea, India, Australia and New Zealand.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-182","question":"The ASEAN Regional Forum (ARF), set up in 1994, is mainly a platform for:","options":["Negotiating a free trade area between ASEAN and its dialogue partners","Coordinating disaster relief among ASEAN's own members","Settling maritime boundary disputes by binding arbitration","Dialogue on political and security issues in the Asia-Pacific"],"answer":3,"explanation":"The ARF is a consultative forum for security dialogue and confidence-building; it makes no binding decisions and has no trade or arbitration role.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-183","question":"Which of these statements about the Regional Comprehensive Economic Partnership (RCEP) are correct? I. It was signed in November 2020. II. India took part in the negotiations but pulled out in 2019. III. It includes the ten ASEAN states with China, Japan, South Korea, Australia and New Zealand. IV. The United States is a member.","options":["I and II only","I, II and III only","II, III and IV only","I, III and IV only"],"answer":1,"explanation":"I, II and III are correct. The United States is not in RCEP; it had earlier withdrawn from the separate Trans-Pacific Partnership in 2017.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-184","question":"SAARC was formally established at its first summit, held in December 1985 in:","options":["Kathmandu","Colombo","New Delhi","Dhaka"],"answer":3,"explanation":"The SAARC Charter was adopted at Dhaka on 8 December 1985; the secretariat was later set up in Kathmandu in 1987.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-185","question":"The South Asian Free Trade Area (SAFTA) agreement was signed at the SAARC summit in ______ and came into force in ______.","options":["Dhaka; 2004","Islamabad; 2004","Islamabad; 2006","Colombo; 2006"],"answer":2,"explanation":"SAFTA was signed at the 12th SAARC summit in Islamabad in January 2004 and took effect on 1 January 2006, succeeding SAPTA (1995).","difficulty":"very-hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-186","question":"BIMSTEC began in June 1997 as 'BIST-EC'. Which four countries founded it?","options":["Bangladesh, India, Myanmar, Thailand","Bhutan, India, Sri Lanka, Thailand","Bangladesh, India, Sri Lanka, Thailand","Bangladesh, India, Maldives, Thailand"],"answer":2,"explanation":"The initials stand for Bangladesh, India, Sri Lanka and Thailand. Myanmar joined later in 1997 (BIMST-EC) and Nepal and Bhutan in 2004.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-187","question":"The BIMSTEC Charter was adopted in 2022 at the grouping's fifth summit, hosted by:","options":["Nepal","Sri Lanka","Thailand","Bangladesh"],"answer":1,"explanation":"Sri Lanka hosted the fifth summit (held in hybrid mode from Colombo) in March 2022, where the Charter was signed. Nepal hosted the fourth summit in Kathmandu in 2018.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-188","question":"The Shanghai Cooperation Organisation grew out of the 'Shanghai Five', formed in 1996 by China, Russia, Kazakhstan, Kyrgyzstan and:","options":["Uzbekistan","Turkmenistan","Tajikistan","Mongolia"],"answer":2,"explanation":"Tajikistan was the fifth member. Uzbekistan joined in 2001, when the group became the SCO; Turkmenistan is not a member and Mongolia is an observer.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-189","question":"Which of these statements about the SCO are correct? I. Its Regional Anti-Terrorist Structure (RATS) is headquartered in Tashkent. II. Chinese and Russian are its official languages. III. Its Charter was signed at St Petersburg in 2002. IV. India and Pakistan became full members at the Bishkek summit of 2019.","options":["I and III only","II, III and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"I, II and III are correct. India and Pakistan became full members at the Astana summit in June 2017, not at Bishkek.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-190","question":"The acronym 'BRIC' for Brazil, Russia, India and China was coined in 2001 by:","options":["Jim O'Neill of Goldman Sachs","Joseph Stiglitz of the World Bank","Paul Krugman of Princeton University","Jeffrey Sachs of Columbia University"],"answer":0,"explanation":"Goldman Sachs economist Jim O'Neill used the term in a 2001 paper on fast-growing economies; the countries began meeting as a group only later.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-191","question":"The first summit of the BRIC countries was held in 2009 at:","options":["Brasília","New Delhi","Rio de Janeiro","Yekaterinburg"],"answer":3,"explanation":"Yekaterinburg, Russia, hosted the first summit in June 2009. Sanya, China, hosted the 2011 summit, the first attended by South Africa.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-192","question":"Which of these statements about the G20 are correct? I. It began in 1999 as a forum of finance ministers and central bank governors after the Asian financial crisis. II. Its first leaders' summit was held in Washington, D.C., in 2008. III. It has a permanent secretariat in Geneva. IV. Each presidency works with a troika of the previous, current and next presidencies.","options":["I, II and IV only","I and II only","I, III and IV only","II, III and IV only"],"answer":0,"explanation":"I, II and IV are correct. The G20 has no permanent secretariat; the presidency country runs it for that year.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-193","question":"The first summit of what became the G7 was held in 1975 at Rambouillet with six countries. Which country joined in 1976 to make it seven?","options":["Canada","Italy","Japan","Russia"],"answer":0,"explanation":"Canada joined at the 1976 Puerto Rico summit. Italy was already at Rambouillet; Russia joined in 1997 to form the G8 and was suspended in 2014.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-194","question":"The G4, whose members back one another's bids for permanent seats in the UN Security Council, are India, Brazil, Germany and:","options":["Japan","South Africa","Indonesia","Italy"],"answer":0,"explanation":"The G4 are India, Brazil, Germany and Japan. Italy leads the rival 'Uniting for Consensus' group that opposes new permanent seats.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-195","question":"In the debate on Security Council reform, the 'Uniting for Consensus' group (which includes Italy and Pakistan):","options":["Backs permanent seats without a veto for India, Brazil, Germany and Japan","Opposes new permanent seats and favours more elected, non-permanent seats","Demands two permanent seats with full veto rights for African countries","Wants the veto abolished and the permanent seats rotated among regions"],"answer":1,"explanation":"Uniting for Consensus resists any new permanent members. The G4 seek permanent seats, and the African Union's Ezulwini Consensus asks for two permanent African seats with veto.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-196","question":"The Group of 77 was formed in 1964 through a joint declaration issued at the end of the first session of:","options":["The Non-Aligned Movement summit at Belgrade","The UN Conference on Trade and Development","The Asian–African Conference at Bandung","The UN Conference on the Human Environment"],"answer":1,"explanation":"Seventy-seven developing countries signed the joint declaration at the close of UNCTAD I in Geneva in June 1964. Belgrade (1961) and Bandung (1955) came earlier; Stockholm was in 1972.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-197","question":"In WTO farm negotiations, the G-33 coalition of developing countries, which includes India, mainly seeks:","options":["Rapid elimination of all farm subsidies and tariffs by every WTO member","Removal of the cotton subsidies that rich countries pay to their own cotton farmers","Binding WTO rules to stop the patenting of traditional knowledge abroad","Flexibilities for developing countries on food security and special products"],"answer":3,"explanation":"The G-33 pushes for special products, a special safeguard mechanism and food-security stockholding. Full liberalisation is the Cairns Group's line and cotton the focus of the 'Cotton Four'.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-198","question":"Which of these leaders was NOT one of the founders of the Non-Aligned Movement at Belgrade in 1961?","options":["Josip Broz Tito","Zhou Enlai","Gamal Abdel Nasser","Sukarno"],"answer":1,"explanation":"NAM's founding figures were Nehru, Tito, Nasser, Sukarno and Kwame Nkrumah. Zhou Enlai attended Bandung (1955), but China never joined NAM.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-199","question":"The Panchsheel principles were first formally stated in the 1954 agreement between India and China on:","options":["The boundary between Ladakh and Xinjiang in Aksai Chin","Trade and intercourse between Tibet and India","Sharing the waters of the Brahmaputra","Mutual recognition of the status of Sikkim"],"answer":1,"explanation":"The five principles formed the preamble of the April 1954 agreement on trade and intercourse between the Tibet region of China and India; they were later echoed at Bandung and in NAM.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-200","question":"The London Declaration of 1949 is a landmark for the Commonwealth because it:","options":["Allowed India to stay a member as a republic, accepting the King as Head of the Commonwealth","Set up the Commonwealth Secretariat at Marlborough House in London to coordinate members' work","Laid down the shared values of all members in a single written Commonwealth Charter","Admitted the first member state with no historical link to the British Empire"],"answer":0,"explanation":"The Declaration let republics remain members, recognising the monarch only as Head of the Commonwealth. The Secretariat came in 1965, the Charter in 2012–13 and the first member without a British link (Mozambique) in 1995.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-201","question":"Which of these Commonwealth members was never under British rule?","options":["Seychelles","Cyprus","Kenya","Mozambique"],"answer":3,"explanation":"Mozambique, a former Portuguese colony, joined in 1995 as the first member with no historical link to the British Empire; Rwanda followed in 2009.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-202","question":"The League of Arab States was founded in March 1945 at:","options":["Riyadh","Damascus","Cairo","Baghdad"],"answer":2,"explanation":"The Arab League's pact was signed in Cairo, which also hosts its headquarters (it moved to Tunis from 1979 to 1990).","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-203","question":"Which of these countries is NOT a member of the Gulf Cooperation Council, founded in 1981?","options":["Oman","Bahrain","Qatar","Iraq"],"answer":3,"explanation":"The GCC's six members are Saudi Arabia, the UAE, Kuwait, Qatar, Bahrain and Oman; Iraq has never been a member. Its secretariat is in Riyadh.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-204","question":"The European Coal and Steel Community, the first step towards today's European Union, was created by the:","options":["Treaty of Rome (1957)","Treaty of Paris (1951)","Treaty of Brussels (1948)","Treaty of Maastricht (1992)"],"answer":1,"explanation":"The 1951 Treaty of Paris set up the ECSC among six states; the Treaties of Rome (1957) created the EEC and Euratom, and Maastricht created the EU.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-205","question":"Match the body with the city where it is based. A. European Central Bank  B. Court of Justice of the European Union  C. European Commission  D. Europol; 1. Brussels  2. The Hague  3. Frankfurt  4. Luxembourg","options":["A-3, B-2, C-1, D-4","A-1, B-4, C-3, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"The ECB is in Frankfurt, the Court of Justice in Luxembourg, the Commission in Brussels and Europol, the EU police agency, in The Hague.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-206","question":"The withdrawal clause used by the United Kingdom to leave the European Union in 2020, Article 50 of the Treaty on European Union, was introduced by the:","options":["Treaty of Maastricht","Treaty of Amsterdam","Treaty of Lisbon","Treaty of Nice"],"answer":2,"explanation":"The Treaty of Lisbon (in force from December 2009) added the first explicit exit procedure; the UK triggered it in 2017 and left on 31 January 2020.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-207","question":"Euro banknotes and coins went into circulation on 1 January of:","options":["1999","2002","2001","2004"],"answer":1,"explanation":"The euro existed from 1999 only as book money; cash followed on 1 January 2002 and national currencies were withdrawn within weeks.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-208","question":"Which of these statements about the Schengen Area are correct? I. The Schengen Agreement was signed in 1985 in Luxembourg. II. Every member of the European Union is part of the Schengen Area. III. Some non-EU countries, such as Norway and Switzerland, belong to the Schengen Area. IV. Ireland has stayed outside the Schengen Area.","options":["I and III only","II, III and IV only","I, II and III only","I, III and IV only"],"answer":3,"explanation":"Schengen is a village in Luxembourg where the 1985 agreement was signed. Not every EU state is in the area (Ireland has opted out), while non-EU Norway, Iceland, Switzerland and Liechtenstein are.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-209","question":"NATO's Article 5, under which an armed attack on one member is treated as an attack on all, has been invoked:","options":["Only once, after the 11 September 2001 attacks on the United States","Only once, after North Korea invaded South Korea in June 1950","Twice, in the Gulf War of 1991 and after the attacks of 2001","Never, because no member has formally asked for it to be used"],"answer":0,"explanation":"Article 5 was invoked for the only time on 12 September 2001. Korea was a UN action, and the 1991 Gulf War was not fought under Article 5.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-210","question":"The Warsaw Pact, the Soviet-led military alliance, was formed in May 1955 as a direct response to:","options":["The founding of NATO in 1949","West Germany's entry into NATO","The launch of the Marshall Plan","The Treaty of Rome setting up the EEC"],"answer":1,"explanation":"The Warsaw Pact was signed days after West Germany joined NATO in May 1955; NATO itself had been founded six years earlier, and the Treaty of Rome came in 1957.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-211","question":"The African Union, which replaced the Organisation of African Unity, was formally launched in July 2002 at:","options":["Addis Ababa","Lomé","Sirte","Durban"],"answer":3,"explanation":"The AU was launched at Durban, South Africa. The 1999 Sirte Declaration called for it and its Constitutive Act was adopted at Lomé in 2000; its seat is Addis Ababa.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-212","question":"The Organisation of African Unity was founded in May 1963 at:","options":["Accra","Addis Ababa","Cairo","Dar es Salaam"],"answer":1,"explanation":"Thirty-two independent African states signed the OAU Charter at Addis Ababa, which remains the seat of its successor, the African Union.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-213","question":"Mercosur, the South American trade bloc, was set up in 1991 by the Treaty of:","options":["Montevideo","Ouro Preto","Asunción","Brasília"],"answer":2,"explanation":"Argentina, Brazil, Paraguay and Uruguay signed the Treaty of Asunción in 1991. The 1994 Ouro Preto Protocol gave the bloc its institutions; Montevideo hosts its secretariat.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-214","question":"Which of these countries is NOT a member economy of the Asia-Pacific Economic Cooperation (APEC) forum?","options":["Peru","Vietnam","Russia","India"],"answer":3,"explanation":"India has sought APEC membership but is not a member; Peru, Vietnam and Russia were the last to join, in 1998, after which APEC froze new admissions.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-215","question":"The Commission of the Economic Community of West African States (ECOWAS) is headquartered in:","options":["Abuja","Accra","Dakar","Lagos"],"answer":0,"explanation":"The ECOWAS Commission is in Abuja, Nigeria. The community was founded by the Treaty of Lagos in 1975, which is a common trap.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-216","question":"Which of these statements about the Treaty on the Non-Proliferation of Nuclear Weapons (NPT) are correct? I. It was opened for signature in 1968 and came into force in 1970. II. It was extended indefinitely in 1995. III. It recognises as nuclear-weapon states only those that exploded a nuclear device before 1 January 1967. IV. India signed it in 1974 but never ratified it.","options":["I, II and III only","I and II only","II, III and IV only","I, III and IV only"],"answer":0,"explanation":"I, II and III are correct. India has never signed the NPT, calling it discriminatory, because the 1967 cut-off freezes the five nuclear powers.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-217","question":"The Comprehensive Nuclear-Test-Ban Treaty (1996) has still not entered into force because:","options":["It needs ratification by two-thirds of all UN members, a mark it has not reached","Its verification system, run from Vienna, has not yet been completed or certified","It must be ratified by all 44 states listed in its Annex 2, and several have not done so","The Security Council has not passed the resolution needed to bring it into effect"],"answer":2,"explanation":"Entry into force needs all 44 Annex 2 states (those with nuclear reactors or research capacity in 1996); India, Pakistan and North Korea have not signed, and some others have not ratified.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-218","question":"The Partial Test Ban Treaty of 1963, which India joined, prohibits nuclear test explosions everywhere EXCEPT:","options":["In outer space","Under water","In the atmosphere","Underground"],"answer":3,"explanation":"The PTBT bans tests in the atmosphere, outer space and under water, but not underground, which is why India's 1974 and 1998 tests were underground.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-219","question":"Which statement about the Biological Weapons Convention (1972) is correct?","options":["It was the first treaty to ban a whole category of weapons of mass destruction, but has no formal verification body","It is verified through routine inspections of member states by the OPCW from its headquarters at The Hague","It allows members to keep limited stocks of biological agents for use only in retaliation against an attack","It binds only those members that hold nuclear weapons, leaving all others free to research biological agents"],"answer":0,"explanation":"The BWC (in force 1975) bans development, production and stockpiling of biological weapons but lacks a verification agency; the OPCW verifies the separate Chemical Weapons Convention.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-220","question":"The Outer Space Treaty of 1967 provides that:","options":["Only permanent members of the Security Council may place satellites in geostationary orbit","Nuclear weapons may be placed in Earth orbit as long as they are meant only for defence","No state may claim sovereignty over the Moon or other celestial bodies by any means","Minerals mined on the Moon become the property of the state whose firms extract them"],"answer":2,"explanation":"Article II bars national appropriation of outer space and celestial bodies, and Article IV bans placing nuclear weapons in orbit; it says nothing that reserves orbits for any state.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-221","question":"India is a party to most global disarmament treaties. Which one of these has India NOT joined?","options":["Chemical Weapons Convention","Biological Weapons Convention","Partial Test Ban Treaty","Ottawa Mine Ban Treaty"],"answer":3,"explanation":"India has not joined the 1997 Ottawa Treaty banning anti-personnel landmines, citing security needs on its borders; it is a party to the CWC, BWC and PTBT.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-222","question":"In which order did India join these export-control regimes? 1. Australia Group  2. Missile Technology Control Regime  3. Wassenaar Arrangement","options":["3-2-1","2-1-3","2-3-1","1-2-3"],"answer":2,"explanation":"India joined the MTCR in June 2016, the Wassenaar Arrangement in December 2017 and the Australia Group in January 2018; it is still outside the Nuclear Suppliers Group.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-223","question":"The Australia Group, an export-control regime that India joined in 2018, aims to stop the spread of:","options":["Ballistic missiles and cruise missiles","Chemical and biological weapons","Conventional arms and dual-use goods","Nuclear materials and reactor technology"],"answer":1,"explanation":"Formed in 1985 after chemical weapons were used in the Iran–Iraq war, it harmonises controls on chemical and biological items. Missiles fall under the MTCR, conventional arms under Wassenaar and nuclear items under the NSG.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-224","question":"The four Geneva Conventions of 1949 and their Additional Protocols form the core of:","options":["International refugee law, which defines who is a refugee and bars sending them back","International humanitarian law, which protects people not or no longer taking part in fighting","International human rights law, which guarantees civil and political rights in peacetime","The law of the sea, which governs the passage of warships through territorial waters"],"answer":1,"explanation":"The Geneva Conventions regulate conduct in armed conflict, protecting the wounded, prisoners of war and civilians; refugee law rests on the separate 1951 Refugee Convention.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-225","question":"Assertion (A): India is not a party to the 1951 Refugee Convention or its 1967 Protocol. Reason (R): The UN High Commissioner for Refugees has no office in India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"India has not signed the Convention and handles refugees under its own laws, but UNHCR does work in India from an office in New Delhi, so R is false.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-226","question":"An Interpol 'Red Notice' is a request to law-enforcement agencies worldwide to:","options":["Locate and provisionally arrest a person pending extradition or similar action","Collect more information about a person's identity, location or activities","Warn of a person whose criminal activities may threaten public safety","Help find a missing person, often a minor, or identify a person who cannot do so"],"answer":0,"explanation":"A Red Notice seeks the location and provisional arrest of a wanted person. Blue notices seek information, Green notices warn about criminals and Yellow notices concern missing persons.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-227","question":"The Convention on the Prevention and Punishment of the Crime of Genocide was adopted by the UN General Assembly in:","options":["1945","1966","1948","1998"],"answer":2,"explanation":"It was adopted on 9 December 1948, a day before the Universal Declaration of Human Rights. 1966 brought the two human rights Covenants and 1998 the Rome Statute.","difficulty":"moderate","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-228","question":"Which of these was NOT adopted at the Rio Earth Summit of June 1992, but separately at a later date?","options":["Agenda 21","UN Convention to Combat Desertification","Rio Declaration on Environment and Development","The Forest Principles"],"answer":1,"explanation":"Rio called for a desertification treaty, but the UNCCD was adopted only in June 1994 in Paris. Agenda 21, the Rio Declaration and the Forest Principles came out of the 1992 summit, where the UNFCCC and CBD were also opened for signature.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-229","question":"The Nagoya Protocol (2010) under the Convention on Biological Diversity deals with:","options":["Safe handling and transfer of living modified organisms","Phasing down the production and use of hydrofluorocarbons","Access to genetic resources and fair sharing of their benefits","Protection of wetlands of international importance for birds"],"answer":2,"explanation":"Nagoya covers access and benefit-sharing. Living modified organisms fall under the Cartagena Protocol, HFCs under the Kigali Amendment and wetlands under the Ramsar Convention.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-230","question":"The '30 by 30' target of the Kunming–Montreal Global Biodiversity Framework (2022) calls for:","options":["Cutting global greenhouse gas emissions by 30% from 2010 levels by 2030","Conserving at least 30% of the world's land and of its oceans by 2030","Restoring native cover on 30% of the world's cleared forests by 2030","Bringing at least 30% of farmland under organic cultivation by 2030"],"answer":1,"explanation":"Target 3 of the framework, adopted at CBD COP15 in December 2022, seeks effective conservation of at least 30% of terrestrial and of marine areas by 2030.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-231","question":"The Intergovernmental Panel on Climate Change (IPCC) was set up in 1988 by:","options":["The UNFCCC secretariat and UNDP","UNESCO and the World Meteorological Organization","The World Meteorological Organization and UNEP","The World Bank and UNEP"],"answer":2,"explanation":"WMO and UNEP created the IPCC in 1988, four years before the UNFCCC existed; it shared the 2007 Nobel Peace Prize with Al Gore.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-232","question":"The Green Climate Fund, set up under the UNFCCC in 2010, is headquartered at:","options":["Bonn, Germany","Songdo, South Korea","Geneva, Switzerland","Nairobi, Kenya"],"answer":1,"explanation":"The GCF is based in Songdo, Incheon, South Korea. Bonn hosts the UNFCCC secretariat and Nairobi hosts UNEP.","difficulty":"moderate","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-233","question":"The decision to set up a dedicated fund for 'loss and damage' suffered by climate-vulnerable countries was taken in 2022 at:","options":["COP26, Glasgow, UK","COP28, Dubai, UAE","COP25, Madrid, Spain","COP27, Sharm el-Sheikh"],"answer":3,"explanation":"COP27 at Sharm el-Sheikh agreed to create the fund; COP28 at Dubai (2023) made it operational. COP26 produced the Glasgow Climate Pact.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-234","question":"Which of these statements about the Montreal Protocol are correct? I. It was adopted in 1987 to phase out ozone-depleting substances. II. It was the first UN treaty to be ratified by every country in the world. III. The Kigali Amendment brought hydrofluorocarbons under it. IV. Its Multilateral Fund helps developing countries meet their phase-out commitments.","options":["I and III only","I, III and IV only","I, II and IV only","I, II, III and IV"],"answer":3,"explanation":"All four are correct. Universal ratification came in 2009, and the Multilateral Fund (1991) finances phase-out in developing countries such as India.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-235","question":"The International Solar Alliance, launched in 2015 and headquartered at Gurugram, is notable as:","options":["The first UN specialised agency to have its headquarters in South Asia","The first treaty-based international intergovernmental body to be based in India","A body whose membership is legally restricted to countries within the tropics","A body created by a resolution of the UN General Assembly at its 2015 session"],"answer":1,"explanation":"The ISA's framework agreement entered into force in 2017, making it the first treaty-based intergovernmental organisation headquartered in India. Membership, first meant for tropical countries, was later opened to all UN member states.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-236","question":"The Coalition for Disaster Resilient Infrastructure (CDRI), launched by India in 2019 at the UN Climate Action Summit in New York, has its secretariat in:","options":["Geneva","Gurugram","Bengaluru","New Delhi"],"answer":3,"explanation":"CDRI's secretariat is in New Delhi. Gurugram is the seat of the separate International Solar Alliance.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-237","question":"Which of these statements are correct? I. The Arctic Council was set up by the Ottawa Declaration of 1996. II. India has been an observer of the Arctic Council since 2013. III. Observer states have voting rights in the Council's decisions. IV. India's Arctic research station, Himadri, is at Ny-Ålesund in Svalbard, Norway.","options":["I, II and IV only","I and II only","II, III and IV only","I, III and IV only"],"answer":0,"explanation":"I, II and IV are correct. Decisions are taken by consensus of the eight Arctic states; observers such as India cannot vote. Himadri opened in 2008.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-238","question":"The International Tribunal for the Law of the Sea, set up under UNCLOS, sits at:","options":["Kingston","The Hague","Hamburg","Montego Bay"],"answer":2,"explanation":"ITLOS is in Hamburg, Germany. Kingston, Jamaica, hosts the International Seabed Authority, and Montego Bay is where UNCLOS was signed.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-239","question":"Under UNCLOS, which maritime zone is correctly paired with its maximum breadth measured from the baseline?","options":["Territorial sea — 6 nautical miles","Exclusive economic zone — 150 nautical miles","Contiguous zone — 24 nautical miles","Contiguous zone — 12 nautical miles"],"answer":2,"explanation":"The territorial sea may extend to 12 nm, the contiguous zone to 24 nm and the exclusive economic zone to 200 nm from the baseline.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-240","question":"The UN Convention on the Law of the Sea was opened for signature in 1982 at:","options":["Montego Bay, Jamaica","Kingston, Jamaica","Geneva, Switzerland","New York, USA"],"answer":0,"explanation":"UNCLOS was signed at Montego Bay in December 1982 and entered into force in 1994. Kingston is the seat of the International Seabed Authority.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-241","question":"Henri Dunant was moved to found the Red Cross movement after seeing the wounded left on the battlefield of:","options":["Waterloo","Sevastopol","Sedan","Solferino"],"answer":3,"explanation":"Dunant witnessed the aftermath of Solferino (1859) in northern Italy and wrote 'A Memory of Solferino', which led to the ICRC's founding in Geneva in 1863.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-242","question":"The UN agency created in 1949 specifically to help Palestine refugees is:","options":["UNHCR","UNRWA","OCHA","UNFPA"],"answer":1,"explanation":"UNRWA (UN Relief and Works Agency) predates UNHCR (1950); Palestine refugees in its areas of operation fall under UNRWA rather than UNHCR.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-243","question":"The 'International Bill of Human Rights' consists of the Universal Declaration of Human Rights together with:","options":["The two International Covenants of 1966 on civil-political and on economic-social rights","The four Geneva Conventions of 1949 and the Refugee Convention adopted in 1951","The Convention on the Rights of the Child and the women's rights convention CEDAW","The European and the American human rights conventions adopted after the war"],"answer":0,"explanation":"The UDHR (1948), the ICCPR and the ICESCR (both adopted in 1966, in force 1976) and the ICCPR's optional protocols make up the International Bill of Human Rights.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-244","question":"The post of UN High Commissioner for Human Rights was created in 1993, following the World Conference on Human Rights held at:","options":["Geneva","Beijing","Vienna","Copenhagen"],"answer":2,"explanation":"The 1993 Vienna Declaration and Programme of Action recommended the post, and the General Assembly created it that December. Beijing (1995) hosted the women's conference.","difficulty":"hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-245","question":"Which of these statements are correct? I. The 17 Sustainable Development Goals were adopted by the UN General Assembly in 2015 as part of the 2030 Agenda. II. The SDGs have 169 targets. III. The eight Millennium Development Goals covered the period up to 2015. IV. Like the MDGs, the SDGs apply only to developing countries.","options":["I and II only","II, III and IV only","I, II and III only","I, III and IV only"],"answer":2,"explanation":"I, II and III are correct. Unlike the MDGs, which targeted developing countries, the SDGs are universal and apply to all countries.","difficulty":"very-hard","source":"UPSC Prelims"},
  {"id":"gk-international-orgs-246","question":"The UN General Assembly declared 2023 the International Year of Millets on a proposal from:","options":["Nigeria","Ethiopia","India","China"],"answer":2,"explanation":"India sponsored the resolution, adopted in March 2021; FAO led the observance in 2023.","difficulty":"moderate","source":"SSC CGL · State PCS"},
  {"id":"gk-international-orgs-247","question":"The UN General Assembly resolution declaring 21 June as the International Day of Yoga was adopted in:","options":["2014","2016","2015","2021"],"answer":0,"explanation":"The resolution was adopted on 11 December 2014, after India proposed it that September. 2015 is the year of the first observance, 2016 is when yoga entered UNESCO's intangible heritage list, and 2021 is when India's millets resolution was adopted.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-248","question":"The World Organisation for Animal Health, founded in 1924 as the OIE, is headquartered in:","options":["Rome","Geneva","Bern","Paris"],"answer":3,"explanation":"WOAH is based in Paris. Rome hosts FAO and Geneva hosts WHO, its partners on animal and human health.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS"},
  {"id":"gk-international-orgs-249","question":"The Codex Alimentarius Commission, which sets international food standards, was set up in 1963 jointly by:","options":["FAO and WHO","FAO and the WTO","WHO and UNICEF","WFP and IFAD"],"answer":0,"explanation":"Codex is a joint FAO/WHO body with its secretariat in Rome; the WTO's SPS Agreement later made Codex standards a reference point in trade disputes.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
  {"id":"gk-international-orgs-250","question":"The International Energy Agency, which India joined as an association country in 2017, was created in 1974 mainly in response to:","options":["The 1960 founding of OPEC by five oil-exporting countries","The 1973 oil crisis, to coordinate responses to supply cuts","The collapse of the Bretton Woods fixed exchange rate system","The need to control the spread of civilian nuclear technology"],"answer":1,"explanation":"Set up within the OECD framework after the 1973–74 Arab oil embargo, the IEA coordinates emergency oil stocks; nuclear safeguards are the IAEA's job.","difficulty":"hard","source":"UPSC Prelims · State PCS"},
];

export default questions;
